## 5. SSL 配置片段（certbot 自动添加，或手动使用）

```nginx
# 在 certbot 成功后，server block 会自动添加以下内容。
# 如需手动配置，可使用此模板：

server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name {{DOMAIN}};

    ssl_certificate /etc/letsencrypt/live/{{DOMAIN}}/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/{{DOMAIN}}/privkey.pem;

    # SSL 安全配置
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384;
    ssl_prefer_server_ciphers off;

    # HSTS
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;

    # OCSP Stapling
    ssl_stapling on;
    ssl_stapling_verify on;
    ssl_trusted_certificate /etc/letsencrypt/live/{{DOMAIN}}/chain.pem;

    # ... 其他 location 配置同上 ...
}

# HTTP → HTTPS 重定向
server {
    listen 80;
    listen [::]:80;
    server_name {{DOMAIN}};
    return 301 https://$host$request_uri;
}
```

---

## 6. API 网关模式（路径路由到多个后端）

```nginx
server {
    listen 80;
    listen [::]:80;
    server_name {{DOMAIN}};

    # API v1 → 后端服务 A
    location /api/v1/ {
        proxy_pass http://127.0.0.1:{{PORT_API_V1}}/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # API v2 → 后端服务 B
    location /api/v2/ {
        proxy_pass http://127.0.0.1:{{PORT_API_V2}}/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # 静态前端
    location / {
        root {{STATIC_DIR}};
        try_files $uri $uri/ /index.html;
    }

    # 速率限制（API 保护）
    limit_req_zone $binary_remote_addr zone=api:10m rate=10r/s;
    location /api/ {
        limit_req zone=api burst=20 nodelay;
        proxy_pass http://127.0.0.1:{{PORT_API_V1}}/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }

    access_log /var/log/nginx/{{DOMAIN}}_access.log;
    error_log /var/log/nginx/{{DOMAIN}}_error.log;
}
```

---

## 变量说明

| 变量 | 说明 | 示例 |
|------|------|------|
| `{{DOMAIN}}` | 域名 | `example.com` |
| `{{APP_NAME}}` | 应用名称 | `my-api` |
| `{{PORT}}` | 后端端口 | `3000` |
| `{{STATIC_DIR}}` | 静态文件目录 | `/var/www/html` |
| `{{MAX_BODY_SIZE}}` | 最大请求体 | `50m` |
| `{{WS_PATH}}` | WebSocket 路径 | `/ws` |
| `{{LB_METHOD}}` | 负载均衡策略 | `least_conn` |
